function diagnosticSelectionLimit(text:string):number{const t=text.toLowerCase();const m=t.match(/(?:до|от\s*\d+\s*до)\s*(\d+)\s*вариант/)||t.match(/(?:отметь|выбери)\s*1\s*[–-]\s*(\d+)/)||t.match(/1\s*[–-]\s*(\d+)\s*наиболее/);return m?Math.max(1,Number(m[1])):1;}
