 {view==="track"&&<section className={`work-card ${grade<=4?"primary-adventure":""}`}><span className="eyebrow">{grade<=4?"ПРИКЛЮЧЕНИЕ СО СНЕГУРОЧКОЙ И ЛЕШИМ":"НАЧАЛО ИССЛЕДОВАНИЯ"}</span><h1>{grade<=4?"Моё путешествие открытий":"Выбери способ тестирования"}</h1>{grade<=4&&ownStage==="select"&&<div className="primary-guides"><img src="/assets/mascots/snegurochka/snegurochka_greet_left.png" alt="Снегурочка"/><div className="primary-guide-bubble" role="note">Привет! Вместе мы узнаем, что тебе нравится. Отвечай так, как думаешь!</div><img src="/assets/mascots/leshii/leshii_wave_left.png" alt="Леший"/></div>}{(grade>4||ownStage==="select")&&<p className="muted">{grade<=4?"Исследуй свои интересы: 13 вопросов анкеты «Билет в будущее» и 6 вопросов Снегурочки и Лешего. В конце тебя ждут идеи занятий и карта открытий.":"Можно пройти полную диагностику самостоятельно или выбрать готовую анкету одного из 15 демо-учеников."}</p>}{ownStage==="select"&&<div className="demo-quiz-actions"><button className="pill primary" onClick={()=>{setError("");setView("demo")}}>Демо: 15 готовых профилей →</button><span className="muted">В демо исходная анкета уже заполнена — останется 6 уточняющих вопросов.</span></div>}{ownStage==="select"&&<h3>Или пройди полную диагностику</h3>}{ownStage==="select"?<><label className="field-label" htmlFor="grade">В каком ты классе?</label><select id="grade" value={grade} onChange={e=>setGrade(+e.target.value)}>{Array.from({length:11},(_,i)=><option key={i} value={i+1}>{i+1} класс</option>)}</select>{grade>4&&<><h3>Как хочешь начать?</h3><div className="option-list">{tracks.map(t=><button key={t.id} className={`option ${track===t.id?"selected":""}`} onClick={()=>setTrack(t.id)}><strong>{t.title}</strong><small>{t.sub}</small></button>)}</div></>}<button className="pill primary" disabled={busy} onClick={start}>{busy?"Загружаем…":"Продолжить →"}</button></>:<div className="diagnostic-panel">{grade<=4&&<div className="primary-guides"><img src="/assets/mascots/snegurochka/snegurochka_pointing.png" alt="Снегурочка"/><div className="primary-guide-bubble" role="note">Не спеши! Выбери то, что больше подходит тебе.</div><img src="/assets/mascots/leshii/leshii_compass_left.png" alt="Леший"/></div>}<span className="eyebrow">{grade<=4?"ЛЕС ИНТЕРЕСОВ":"ИСХОДНАЯ АНКЕТА"} · {di+1} ИЗ {diagnostic.length}</span>{grade<=4&&<><p className="muted">🌲 Леший собирает подсказки о том, что тебе интересно. Здесь нет неправильных ответов!</p><progress aria-label="Прогресс путешествия" value={di+1} max={diagnostic.length} style={{width:"100%",accentColor:"#38a789"}}/></>}<h2>{diagnostic[di]?.text?.replace(/\s*\([^)]*(?:выбрать|вариант|ответ)[^)]*\)\s*$/i,"").trim()}</h2>{diagnostic[di]?.maxSelections>1&&<p className="muted">Можно выбрать до {diagnostic[di].maxSelections} вариантов · Выбрано: {(dAnswers[diagnostic[di].id]||[]).length}</p>}<div className="option-list">{(diagnostic[di]?.options||[]).map(rawOption=>{const o=typeof rawOption==="string"?{value:rawOption,label:rawOption}:rawOption;return <button key={o.value} className={`option ${(dAnswers[diagnostic[di].id]||[]).includes(o.value)?"selected":""}`} onClick={()=>choose(diagnostic[di].id,o.value,diagnostic[di].maxSelections>1,diagnostic[di].maxSelections)}>{o.label}</button>})}</div>{!(diagnostic[di]?.options||[]).length&&<input aria-label="Твой ответ" placeholder="Введи ответ" value={dAnswers[diagnostic[di]?.id]?.[0]||""} onChange={e=>setDAnswers(a=>({...a,[diagnostic[di].id]:[e.target.value]}))}/>}<div className="demo-quiz-actions"><button className="pill outline" onClick={()=>di===0?setOwnStage("select"):setDi(v=>v-1)}>← Назад</button><button className="pill primary" disabled={!dAnswers[diagnostic[di]?.id]?.[0]} onClick={nextOwnDiagnostic}>{di===diagnostic.length-1?"Перейти к 6 уточнениям →":"Далее →"}</button></div></div>}</section>}
 {view==="profile"&&<section className="vector-results"><div className="vector-results-hero"><img src="/assets/mascots/snegurochka/snegurochka_celebrate.png" alt="Снегурочка" /><div className="vector-results-intro"><span className="vector-results-status">✓ Диагностика завершена · Этап 1 из 5</span><h1>Мой профиль интересов</h1><p>{result?.summary||"Это твой первый портрет интересов на основе ответов. Он поможет исследовать разные направления."}</p>{demoAiNotice&&<p role="status" className="muted">{demoAiNotice}</p>}</div><img src="/assets/mascots/leshii/leshii_checklist.png" alt="Леший" /></div><div className="vector-profile-review"><div className="vector-profile-intro"><h2>Вот что мы узнали о тебе</h2><p>Мы собрали главное из твоих ответов в небольшой портрет. Это не оценка и не ярлык — интересы могут меняться, а новые занятия помогут узнать себя лучше.</p></div><div className="vector-profile-summary"><img src="/assets/mascots/snegurochka/snegurochka_reading.png" alt="Снегурочка с книгой" /><div><span className="eyebrow">ТВОЙ ПЕРВЫЙ ПОРТРЕТ</span><h2>У тебя уже есть отправная точка</h2><p>{profileInterests.length?"В твоих ответах прослеживаются конкретные интересы. Мы учтём их, когда будем объяснять профессиональные гипотезы.":"Мы опираемся на то, что ты рассказал о себе, и будем уточнять интересы через реальные пробы."}</p></div></div><div className="vector-profile-insights">{profileCards.map(card=><article className="vector-profile-insight" key={card.title}><div className="vector-profile-insight-icon" aria-hidden="true">{card.icon}</div><h3>{card.title}</h3><p>{card.lead}</p><ul>{card.items.map((item,i)=><li key={i}>{item}</li>)}</ul></article>)}{!profileCards.length&&<article className="vector-profile-insight"><h3>Пока недостаточно данных для резюме</h3><p>Мы не будем придумывать твои интересы. Перейди к гипотезам, чтобы изучить доступные направления.</p></article>}</div>{profileThemes.length>0&&<div className="vector-profile-directions"><h2>Что можно исследовать дальше</h2><p>Среди рекомендованных профессий есть такие сферы. Это направления для исследования, а не окончательный выбор.</p><div className="vector-direction-tags">{profileThemes.map(name=><span key={name}>{name}</span>)}</div></div>}<div className="vector-profile-next"><p>На следующем этапе увидишь конкретные профессии и объяснения, почему их стоит рассмотреть.</p><button className="pill primary" onClick={()=>{setView("results");window.scrollTo({top:0,behavior:"smooth"})}}>Посмотреть профессиональные гипотезы <span className="vector-profile-cta-arrow" aria-hidden="true">→</span></button></div></div></section>}
 {view==="results"&&grade<=4&&<PrimaryExperience result={result} grade={grade} scope={routeScope} notice={demoAiNotice} onRestart={()=>setView("home")}/>}
